<?php
require dirname(__DIR__).'/config/bootstrap.php';require_once dirname(__DIR__).'/includes/layout.php';$admin=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf();$action=$_POST['action']??'';$date=$_POST['tanggal']??'';$name=trim((string)($_POST['nama']??''));
 if($action==='delete'&&is_string($date)&&preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)){
  $s=$pdo->prepare('DELETE FROM hari_libur WHERE tanggal=?');$s->execute([$date]);if($s->rowCount())audit_event($pdo,(int)$admin['id'],'holiday.deleted','hari_libur',null,['tanggal'=>$date]);flash($s->rowCount()?'success':'warning',$s->rowCount()?'Hari libur dihapus.':'Tanggal tidak ditemukan.');redirect('/hris-presensi/admin/hari-libur.php');
 }
 $parsed=is_string($date)?DateTimeImmutable::createFromFormat('!Y-m-d',$date):false;$errors=DateTimeImmutable::getLastErrors();
 if($action!=='add'||!$parsed||($errors!==false&&($errors['warning_count']||$errors['error_count']))||$parsed->format('Y-m-d')!==$date||preg_match('/^.{1,120}$/us',$name)!==1){flash('danger','Masukkan tanggal valid dan nama hari libur (maksimal 120 karakter).');redirect('/hris-presensi/admin/hari-libur.php');}
 try{$s=$pdo->prepare('INSERT INTO hari_libur (tanggal,nama,created_by) VALUES (?,?,?)');$s->execute([$date,$name,$admin['id']]);audit_event($pdo,(int)$admin['id'],'holiday.created','hari_libur',null,['tanggal'=>$date,'nama'=>$name]);flash('success','Hari libur ditambahkan ke kalender payroll.');}
 catch(PDOException $e){flash('danger','Tanggal tersebut sudah terdaftar atau data gagal disimpan.');}
 redirect('/hris-presensi/admin/hari-libur.php');
}
$year=max(2020,min(2100,(int)($_GET['tahun']??date('Y'))));$s=$pdo->prepare('SELECT tanggal,nama FROM hari_libur WHERE YEAR(tanggal)=? ORDER BY tanggal');$s->execute([$year]);$rows=$s->fetchAll();page_header('Kalender hari libur'); ?>
<div class="mb-4"><div class="eyebrow">Pengaturan payroll</div><h1 class="page-title">Kalender hari libur</h1><p class="page-subtitle">Tanggal yang dicatat di sini dikeluarkan dari hari kerja payroll dan perhitungan alpha.</p></div>
<div class="row g-4"><div class="col-lg-5"><form method="post" class="panel"><h2 class="h5 fw-bold mb-3">Tambah tanggal libur</h2><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label class="form-label" for="holiday-date">Tanggal</label><input class="form-control mb-3" id="holiday-date" type="date" name="tanggal" required><label class="form-label" for="holiday-name">Nama hari libur</label><input class="form-control mb-4" id="holiday-name" name="nama" maxlength="120" autocomplete="off" required><button class="btn btn-primary w-100">Simpan hari libur</button></form></div>
<div class="col-lg-7"><section class="panel"><div class="d-flex justify-content-between align-items-end gap-3 mb-3"><div><h2 class="h5 fw-bold mb-0">Tanggal terdaftar</h2><p class="small text-secondary mb-0">Payroll tahun <?=$year?></p></div><form method="get"><label class="visually-hidden" for="holiday-year">Tahun</label><input class="form-control" id="holiday-year" type="number" name="tahun" min="2020" max="2100" value="<?=$year?>"><button class="btn btn-outline-secondary btn-sm mt-2">Pilih tahun</button></form></div><div class="table-responsive"><table class="table"><caption class="visually-hidden">Daftar hari libur <?=$year?></caption><thead><tr><th scope="col">Tanggal</th><th scope="col">Nama</th><th scope="col"><span class="visually-hidden">Tindakan</span></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d-m-Y',strtotime($r['tanggal'])))?></td><td><?=e($r['nama'])?></td><td><form method="post" onsubmit="return confirm('Hapus tanggal libur ini?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="tanggal" value="<?=e($r['tanggal'])?>"><button class="btn btn-outline-danger btn-sm" aria-label="Hapus <?=e($r['nama'])?> tanggal <?=e($r['tanggal'])?>">Hapus</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="3" class="text-center text-secondary py-4">Belum ada hari libur untuk tahun ini.</td></tr><?php endif;?></tbody></table></div></section></div></div>
<?php page_footer(); ?>
